def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    x = []
    last = 0.0
    for v in history:
        try:
            z = float(v)
        except (TypeError, ValueError, OverflowError):
            z = last
        if not math.isfinite(z):
            z = last
        x.append(z)
        last = z
    if h == 0:
        return []
    if not x:
        return [0.0] * h
    f = str(frequency).lower()
    preferred = []
    if 'hour' in f:
        preferred = [24, 12, 168]
    elif 'day' in f:
        preferred = [7, 14, 365]
    elif 'week' in f:
        preferred = [52, 26, 13]
    elif 'month' in f:
        preferred = [12, 6, 3]
    elif 'quarter' in f:
        preferred = [4, 2]
    candidates = []
    for lag in preferred + list(range(2, min(60, len(x) // 2) + 1)):
        if lag not in candidates and 2 * lag <= len(x):
            candidates.append(lag)
    def level(prefix):
        w = min(12, len(prefix))
        return float(statistics.median(prefix[-w:])) if w else 0.0
    base_errs = []
    start = max(1, len(x) - min(24, len(x) // 2))
    for t in range(start, len(x)):
        base_errs.append(abs(x[t] - level(x[:t])))
    base_score = float(statistics.median(base_errs)) if base_errs else float('inf')
    ranked = []
    for lag in candidates:
        errs = []
        fold_means = []
        block = []
        for t in range(max(lag, start), len(x)):
            e = abs(x[t] - x[t-lag])
            errs.append(e)
            block.append(e)
            if len(block) >= max(2, lag // 4):
                fold_means.append(sum(block) / len(block))
                block = []
        if block:
            fold_means.append(sum(block) / len(block))
        if errs:
            score = float(statistics.median(errs))
            instability = (max(fold_means) - min(fold_means)) if len(fold_means) > 1 else 0.0
            ranked.append((score + 0.15 * instability, score, lag))
    use_lag = False
    lag = 1
    if ranked:
        ranked.sort()
        _, raw_score, lag = ranked[0]
        use_lag = raw_score <= 0.9 * base_score or (raw_score == 0.0 and base_score == 0.0)
    if not use_lag:
        y = level(x)
        return [y] * h
    out = []
    extended = list(x)
    for _ in range(h):
        y = extended[-lag]
        if not math.isfinite(y):
            y = level(extended)
        out.append(float(y))
        extended.append(float(y))
    return out
